def check_n(n, base):
    digits = []
    temp_n = n
    while temp_n > 0:
        digits.append(temp_n % base)
        temp_n //= base
    m = len(digits) - 1
    a = []
    for i in range(m + 1):
        rem_digits = digits[:i] + digits[i+1:]
        val = 0
        for j in range(len(rem_digits)):
            val += rem_digits[j] * (base ** j)
        a.append(val)
    return a

def test_all_versions(max_n, base):
    v1_solutions = []
    for n in range(1, max_n):
        a = check_n(n, base)
        if n == sum(a):
            v1_solutions.append(n)
    return v1_solutions

print(test_all_versions(100000, 7))

def get_m(n, base):
    m = 0
    while n >= base:
        n //= base
        m += 1
    return m

